class FrmonConnectionFailed(Exception):
    """
    Raised when connection to FRMon has failed.
    """
    pass


class NahkaConnectionFailed(Exception):
    """
    Raised when connection to Nahka node has failed.
    """
    pass


class BtsConnectionFailed(Exception):
    """
    Raised when connection to BTS has failed.
    """
    pass


class CommandExecutionError(Exception):
    """
    Raised when given command is not executed successfully.
    """
    pass


class PIDNotFound(Exception):
    """
    Raised when PID not found for given process name.
    """
    pass


class BMUversionNotFound(Exception):
    """
    Raised when BMU version not found.
    """
    pass
